    public static func text(named name: String) -> String? {
        switch name {
        case "error": error
        case "report": report
        case "report-redacted": report_redacted
        case "report-section": report_section
        case "report-summary": report_summary
        case "scan": scan
        case "schema": schema
        case "sessions-list": sessions_list
        case "sessions-show": sessions_show
        case "skill-check": skill_check
        case "skill-install": skill_install
        case "update": update
        case "version": version
        default: nil
        }
    }
}
